// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this)); // admin is the deployer (this test contract)
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // Universal rule: a successful setOwner implies the caller was the admin (deployer).
        assertTrue(!(ok && caller != address(this)) && (!ok || c.owner() == newOwner));
    }
}
